entries[51485] = { ["name"] = "Totem des Erdgriffs", ["text"] = "Ersetzt Totem der Erdbindung\n5% von Grundmana\nSofort 30 sek. Abklingzeit\nBeschwört ein Erdtotem mit [ Glyphe 'Totemische Lebenskraft' : 5% der Gesundheit des Zaubernden zu dessen Füßen / 5 Gesundheit zu Füßen des Zaubernden], das 20 Sek. lang alle 2 Sek. pulsiert und die Beine aller Gegner im Umkreis von 10 Metern 5 Sek. lang in Wurzeln einschnürt, wodurch sie bewegungsunfähig werden. Gegner, die bereits einmal vom Totem bewegungsunfähig gemacht wurden, erleiden stattdessen eine Verringerung des Bewegungstempos um 50%.\n\nErsetzt 'Totem der Erdbindung'." }
