entries[51663] = { ["name"] = "Schlag ins Gesicht", ["text"] = "5 WutSpontanzauber 1 tag Abklingzeit\nVersetzt allen nahen Spielern eine Ohrfeige und betäubt sie. Ziele, die von dieser Fähigkeit betroffen sind, können noch immer über Foren kommunizieren. Hält an, bis der nächste Patch draußen ist." }
