entries[51676] = { ["name"] = "Wankelmut", ["text"] = "30 Meter Reichweite\nSofort\nErhöht die Zeit zwischen den Angriffen eines Feindes um 25%, verlangsamt sein Zaubertempo um 20% und sein Bewegungstempo um 50%. Hält 15 Sek. lang an." }
entries[51678] = { ["name"] = "Rammen", ["text"] = "20 Energie\nSofort 1.5 sek. Abklingzeit\nRammt alle Feinde, die sich vor dem Verwüster befinden, verursacht 3500 Schaden und stößt sie zurück. Verursacht zudem bei Gebäuden 2000 Belagerungsschaden." }
