entries[51701] = { ["name"] = "Ehre unter Dieben", ["text"] = "Wenn eines Eurer Gruppen- und Schlachtzugsmitglieder mit einem Zauber oder einer Fähigkeit einen kritischen Treffer erzielt, gewinnt Ihr einen zusätzlichen Combopunkt auf Eurem aktuellen Ziel hinzu. Dieser Effekt kann nur einmal alle 2 Sek. auftreten und während Ihr Euch im Kampf befindet.\n(2s Abklingzeit)" }
entries[51702] = { ["name"] = "Spottflaggenziel", ["text"] = "Unbegrenzte Reichweite\nSofort\nPlatziert auf einer feindlichen Leiche vor Euch eine Flagge." }
entries[51713] = { ["name"] = "Schattentanz", ["text"] = "Sofort 1 min Abklingzeit\nBeginnt einen Schattentanz, durch den 8 Sek. lang Fähigkeiten genutzt werden können, die normalerweise Verstohlenheit benötigen. Während 'Schattentanz' aktiv ist, sind die Energiekosten Eurer Fähigkeit 'Hinterhalt' um 20 verringert." }
entries[51714] = { ["name"] = "Frostverletzlichkeit", ["text"] = "Unbegrenzte Reichweite\nSofort\nErfüllt Eure Runenwaffe mit der Macht des Frosts. Bei Euren Nahkampfwaffenschwüngen besteht eine Chance, dass Euer Ziel 20 Sek. lang 3% zusätzlichen Schaden durch Eure Frostangriffe erleidet. Dieser Effekt ist bis zu 5-mal stapelbar." }
