entries[51722] = { ["name"] = "Zerlegen", ["text"] = "25 Energie Nahkampfreichweite\nSofort 1 min Abklingzeit\nEntwaffnet den Feind und verhindert 8 Sek. lang die Nutzung von jeglichen Waffen oder Schilden." }
entries[51723] = { ["name"] = "Dolchfächer", ["text"] = "35 Energie\nSofort\nWirbelt sofort herum und schleudert allen Zielen im Umkreis von 10 Metern einen Klingenregen entgegen, der 1558 körperlichen Schaden verursacht [ Glyphe 'Scharfe Klingen' : und Ziele mit dem Effekt 'Rüstungsschwächung' belegt ]. Dieser Angriff hat eine Chance, Eure Ziele zu einer normalen Rate zu vergiften. Gewährt 1 Combopunkt, wenn Ihr ein Ziel trefft, auf dem bereits Eure Combopunkte aktiv sind." }
entries[51725] = { ["name"] = "Arkane Explosion", ["text"] = "Sofort\nLässt eine Druckwelle aus Magie entstehen und fügt in der Nähe befindlichen Feinden Arkanschaden zu." }
entries[51727] = { ["name"] = "Arkane Entladung", ["text"] = "Sofort\nDie Entladung regeneriert bei Gegnern in der Nähe 20% Mana." }
