entries[51729] = { ["name"] = "Segen von Zim'Torga", ["text"] = "10 Meter Reichweite\nSofort\nBelegt das freundliche Ziel mit einem Segen, der 1 Stunde lang seine gesamten Werte um 10% erhöht. Auf das Gebiet von Zul'Drak beschränkt." }
entries[51730] = { ["name"] = "Waffe der Lebensgeister", ["text"] = "10.5% von Grundmana\nSofort\nBenötigt Nahkampfwaffe\nErfüllt die Waffe des Schamanen mit der Kraft des Lebens. Erhöht die durch Zauber hervorgerufene Heilung um 110 und jede Heilung hat eine Chance von bis zu 20%, den Effekt 'Lebensgeister' auszulösen, der das Ziel im Verlauf von 12 Sek. um zusätzlich 4376 Gesundheit heilt. Auf Ziele mit weniger als 35% Gesundheit gewirkte direkte Einzelzielheilzauber lösen diesen Effekt immer aus. Hält 60 Minuten lang an. [ Elemente entfesseln : Das Entfesseln dieser Verzauberung heilt ein verbündetes Ziel um 3154 und erhöht den Effekt der nächsten direkten Heilung oder von 'Heilender Regen' des Schamanen um 30% ]" }
entries[51731] = { ["name"] = "Überladung", ["text"] = "Sofort\nNach 4 Sek. wird das Ziel von Überladung betroffen. Dieser Effekt fügt Einheiten in der Nähe 8 Sek. lang alle 2 Sek. 220 Arkanschaden zu." }
entries[51732] = { ["name"] = "Arkane Infusion", ["text"] = "400 Mana 15 Meter Reichweite\nKanalisiert (Wirken in 4 sek.)\nErfüllt das Ziel mit arkaner Energie. Nach 4 Sekunden erleidet das Ziel eine Überladung, die Gegnern in der Nähe alle 2 Sek. 220 Arkanschaden zufügt." }
