entries[51753] = { ["name"] = "Camouflage", ["text"] = "20 FokusSpontanzauber 1 min Abklingzeit\nIhr und Euer Tier geht in einen Camouflagezustand über, in dem Ihr nicht als Ziel von Distanzangriffen erfassbar seid [ Glyphe 'Hartnäckige Tarnung' : und Euer erlittener Zauberschaden um 10% verringert wird ]. Die Distanz, auf die Euch gegnerische Kreaturen entdecken können, wird dabei verringert. [ Glyphe 'Camouflage' : Zudem geht Ihr in einen Verstohlenheitszustand über, durch den Euer Bewegungstempo um 50% verringert wird / Zudem geht Ihr, solang Ihr Euch nicht bewegt, in einen Verstohlenheitszustand über.]\nWährend der Camouflageeffekt aktiv ist, könnt Ihr Fallen legen, jedoch wird jeglicher von Euch oder Eurem Tier verursachte Schaden den Effekt abbrechen. Wird diese Fähigkeit im Kampf eingesetzt, hält sie 6 Sek. lang an. Außerhalb des Kampfes hat sie eine Dauer von 1 Min." }
entries[51754] = { ["name"] = "Element-Tamer Dagoda: Frost Channel" }
entries[51755] = { ["name"] = "Camouflage", ["text"] = "Sofort\nIhr und Euer Tier geht in einen Camouflagezustand über, in welchem Ihr nicht als Ziel von Distanzangriffen erfassbar seid [ Glyphe 'Hartnäckige Tarnung' : und Euer erlittener Zauberschaden um 10% verringert wird ]. Zudem geht Ihr, solang Ihr Euch nicht bewegt, in einen Verstohlenheitszustand über und die Distanz, auf welche feindliche Kreaturen Euch entdecken können, wird verringert.\n\nWährend der Camouflageeffekt aktiv ist, könnt Ihr Fallen legen, jedoch wird jeglicher von Euch oder Eurem Tier verursachter Schaden den Effekt abbrechen. Kann nicht im Kampf verwendet werden. Hält 1 Min. lang an." }
